"""Colleague's tests — written against a wrong variant of the rule."""
import unittest

from pricing import quote


class QuoteTest(unittest.TestCase):
    def test_exactly_ten_is_full_price(self):
        self.assertEqual(quote([(100, 10)]), 1000)

    def test_rounds_to_nearest_cent(self):
        self.assertEqual(quote([(333, 11)]), 3297)


if __name__ == "__main__":
    unittest.main()
